import React, { MouseEvent, useCallback } from 'react';
import styled, { CSSObject } from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import Elevations from '@dynatrace/strato-design-tokens/elevations';
import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { mergeProps as _mergeProps } from '../../../core/utils/merge-props.js';

// #region StyledComponents
const StyledResizer = /* @__PURE__ */ styled.div<{
  $isResizing: boolean;
}>(({ $isResizing }) => {
  return {
    position: 'absolute',
    right: `calc(${Spacings.Size8} / -1)`,
    top: Spacings.Size4,

    display: 'inline-block',
    width: Spacings.Size16,
    height: `calc(100% - ${Spacings.Size4} * 2)`,
    userSelect: 'none',
    overflow: 'hidden',
    zIndex: Elevations.Default,

    /* prevents from scrolling while dragging on touch devices */
    touchAction: 'none',

    transform: $isResizing ? 'scaleY(1.2) scaleX(1)' : 'none',

    '::after': {
      content: '""',
      position: 'absolute',
      left: Spacings.Size8,
      top: 0,
      bottom: 0,
      width: `calc(${Spacings.Size2}/2)`,
      backgroundColor: Colors.Border.Neutral.Default,

      ...($isResizing && {
        width: `calc(${Spacings.Size6}/2)`,
        backgroundColor: Colors.Border.Primary.Accent,
        cursor: 'col-resize',
      }),
    },

    '&:hover::after': {
      width: `calc(${Spacings.Size6} / 2)`,
      backgroundColor: Colors.Border.Primary.Accent,
      cursor: 'col-resize',
    },
  } as CSSObject;
});
// #endregion

export type DataTableResizerProps = {
  isResizing: boolean;
};

/**
 * @returns
 */
export const DataTableResizer = (props: DataTableResizerProps) => {
  const { isResizing, ...remainingProps } = props;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const handleResizerClick = useCallback((e: MouseEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  return (
    <StyledResizer
      $isResizing={isResizing}
      {..._mergeProps(remainingProps, { onClick: handleResizerClick })}
    />
  );
};
